// books.js

const BASE_URL = 'https://openlibrary.org/search.json?q=';

/**
 * Fetch books from Open Library API based on a search query.
 * @param {string} query - The search term (e.g., "harry potter").
 * @returns {Promise<Array>} - Array of book objects.
 */
export async function fetchBooks(query) {
  try {
    const response = await fetch(`${BASE_URL}${encodeURIComponent(query)}`);
    const data = await response.json();

    // Map relevant fields from Open Library response
    return data.docs.map(book => ({
      key: book.key,
      title: book.title,
      author: book.author_name?.join(', ') || 'Unknown',
      publishYear: book.first_publish_year || 'N/A',
      coverId: book.cover_i,
      coverUrl: book.cover_i
        ? `https://covers.openlibrary.org/b/id/${book.cover_i}-M.jpg`
        : null,
    }));
  } catch (error) {
    console.error('Error fetching books from Open Library:', error);

    // Optional fallback to local books.json
    try {
      const localResponse = await fetch('/books.json');
      const localData = await localResponse.json();
      return localData;
    } catch (localError) {
      console.error('Error loading local books.json:', localError);
      return [];
    }
  }
}
